            "heading": "Transcripts Unit 1 A school magazine Lesson 2 A new project B Listen and answer the questions. Mazin Hey, Usama! Look at this. Usama What is it? Mazin A magazine. From the girls' school. It's really interesting. Why don't we start a magazine? Usama Mm. I don't know. It'll be a lot of hard Usama Tariq Mazin Tariq Wh0'll be the photographer and take the photographs? I don't have a camera. Do you? Hi, everybody. What are you talking about? Hi, Tariq. Tariq! You have a camera, don't you? Yes. And I'm a good photographer. Why? Mazin Layth Mazin Usama Layth Usama Layth Mazin Layth Usama Layth Mazin Usarna Mazin Usama Mazin Layth Usama Mazin work and Well, if you're not interested, Layth will be. Layth! Have you seen this magazine from the girls' school? Yes, I have. Good, isn't it? Why don't we start one? You see, Usama. I told you. Oh, but it'll be too much work and Oh, come on, Usama. It'll be fun, Oh, all right. Maybe. But who'll decide what goes into the magazine? We'll need an editor. Just a minute! Mazin, you're good at English. Why don't you be the editor? You're good at English. too, Layth. But I want to be a reporter. I think you'll be a good editor, Mazin. Don't you, Usama? Yes, great! Fantastic! Mazin is really good at English, and he's good at telling people what to do. Exactly! Come on, Mazin. Oh, all right then, I'll be the editor. And you want to be a reporter, Layth? Can I be a reporter, too? Of course. You write very well. But I thought you didn't want to . Well you know . Right. We have an editor and two reporters. That's a good start. Now - what sections shall we have? There's a list in the girls' magazine. We don't want all these, do we? No, no. There are too many. Let's have articles about the school. I agree, but can't we have some articles about things outside the school? Like the interview. Lesson 4 An interview (Part B) A Listen to the interview. Then read it aloud. Interviewer This month, we talked to Jack James. He runs Pizza Cabin, the well-known Italian takeaway and café in the High Street. I'm sure we've all been there many times with our families. How long have you worked at Pizza Cabin, Mr James? Mr James I've worked in the café for ten years, but I've lived in Ashby since I was born. Interviewer Do you enjoy your work? Mr James I enjoy some parts of my work. I don't enjoy cleaning up when the café closes. Interviewer What do you like doing in your spare time? Mr James I love painting. Interviewer What things do you dislike doing? Mr James I don't like washing-up. I have to do that at work. And I hate gardening. It's very hard work. But we have a beautiful garden because my wife loves gardening, Interviewer What kind of people do you like and dislike? Mr James I really like people who are polite and ask for things nicely. I don't like people who are impolite and shout. Interviewer What's your favourite food? Mr James Italian food, of course - pizzas and pasta, But I also like some English food, like fish and chips. Interviewer What's your favourite TV programme? Mr James I watch all the programmes about cooking. My favourite one is A taste of the sea. I always learn something. 90 Transcripts",
