            "heading": "Transcripts Story time Jad and Johnny - Camping at Stonehenge A Listen, read and find out. For the story text, see pages 26-27. Unit 3 Sports Lesson I The sports centre A Listen and point. Repeat the names of the sports. Voice 1 Voice 2 Voice 1 Voice 2 Voice 1 Voice 2 Voice 1 Voice 2 Voice I Voice 2 Voice 1 Voice 2 Voice 1 Voice 2 Ashby Sports Centre. Come to the sports centre and get fit! You can choose from last year's old favourites. Volleyball (Pause) Swimming (Pause) Sailing (Pause) Horse riding (Pause) Football (Pause) Judo (Pause) Basketball (Pause) And, from the beginning of this year, we can give you lessons in these sports: Karate (Pause) Tennis (Pause) Athletics (Pause) Gymnastics (Pause) Call us on 952841 for more information, Lesson 2 The timetable A Listen to the message. What does Dave have to leave? This is the Ashby Sports Centre. Thank you for calling. We hold classes in many different sports, from tennis to horse riding. We have separate classes for women and girls and for men and boys. There are three kinds of classes: beginners, advanced and team practice. Please leave your name and address, and we'll send you a leaflet. Thank you for calling. B Listen and repeat the words. beginners advanced team practice 94 Transcripts",
