          {
            "id": 597,
            "page": 110,
            "heading": "Grammar and functions reference Unit 1 Possessive 's' Form Singular My sister's friend. Singular The child's father. Use Regular plural My sisters' friend. Irregular plural The children's father. We use the possessive •s' to say when an object belongs to someone or to something. In the singular, the apostrophe comes before the s. The child's father. (one child) My sister's friend. (one sister + one friend) In the plural, the apostrophe comes after the s. My sisters' friend. (more than one sister + one friend) When using the possessive 's' with irregular plurals, the apostrophe comes before the s. The children's father. (two or more children) Common irregular plural nouns include: child - children; woman - women; man - men; person - people. for and since Form for + period of time (e.g., two weeks, three years) since + specific time or event (e.g., 2015, school started) Use We use forto talk about the length of time or duration of an event. I have lived in Basra for ten years. She has been asleep for three hours. My parents have been married for 15 years. We use since to say when a period of time or an event started in the past. I have lived in Basra since I was born. She has been asleep since she got home from school. My parents have known each other since 2004. Grammar and functions reference",
            "text": "Grammar and functions reference Unit 1 Possessive 's' Form Singular My sister's friend. Singular The child's father. Use Regular plural My sisters' friend. Irregular plural The children's father. We use the possessive •s' to say when an object belongs to someone or to something. In the singular, the apostrophe comes before the s. The child's father. (one child) My sister's friend. (one sister + one friend) In the plural, the apostrophe comes after the s. My sisters' friend. (more than one sister + one friend) When using the possessive 's' with irregular plurals, the apostrophe comes before the s. The children's father. (two or more children) Common irregular plural nouns include: child - children; woman - women; man - men; person - people. for and since Form for + period of time (e.g., two weeks, three years) since + specific time or event (e.g., 2015, school started) Use We use forto talk about the length of time or duration of an event. I have lived in Basra for ten years. She has been asleep for three hours. My parents have been married for 15 years. We use since to say when a period of time or an event started in the past. I have lived in Basra since I was born. She has been asleep since she got home from school. My parents have known each other since 2004. Grammar and functions reference"
          },
          {
            "id": 598,
            "page": 111,
            "heading": "Grammar and functions reference like + noun, -ing, or adjective + noun Form Subject I / You / We / They He / She / It Subject I / You / We / They He / She / It Subject I / You / we / They He / She / It Use like like like Noun like likes like likes like likes football. football. Verb + -ing cooking. running. Adjective + noun exciting sports. complicated games. Some verbs have a special grammu For example, like can be followed by a noun, a gerund, or an adjective and noun. Other common verbs that follow a similar pattern include: avoid, enjoy, hate. dislike, finish and start. He hates bikes. He enjoys cycling. He dislikes fast games. Unit 2 should/shouldn 't Form Subject I / You / He / She / It/ we / They Use Affirmative should + infinitive without to Negative shouldn't + infinitive without to We use should and shouldn't when we are giving advice to mean that, in our opinion, something is a good idea or a bad idea. Should and shouldn't are always followed by the infinitive without to. We should go home now because it's getting late. You've got an exam tomorrow - you shouldn't stay up late. Grammar and functions reference",
            "text": "Grammar and functions reference like + noun, -ing, or adjective + noun Form Subject I / You / We / They He / She / It Subject I / You / We / They He / She / It Subject I / You / we / They He / She / It Use like like like Noun like likes like likes like likes football. football. Verb + -ing cooking. running. Adjective + noun exciting sports. complicated games. Some verbs have a special grammu For example, like can be followed by a noun, a gerund, or an adjective and noun. Other common verbs that follow a similar pattern include: avoid, enjoy, hate. dislike, finish and start. He hates bikes. He enjoys cycling. He dislikes fast games. Unit 2 should/shouldn 't Form Subject I / You / He / She / It/ we / They Use Affirmative should + infinitive without to Negative shouldn't + infinitive without to We use should and shouldn't when we are giving advice to mean that, in our opinion, something is a good idea or a bad idea. Should and shouldn't are always followed by the infinitive without to. We should go home now because it's getting late. You've got an exam tomorrow - you shouldn't stay up late. Grammar and functions reference"
          }
